  "4-6-tree-late": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 470 250\" role=\"img\" aria-labelledby=\"t\">\n  <title id=\"t\">Tree diagram. First stage: rain 0.3, no rain 0.7. After rain: late 0.25, on time 0.75. After no rain: late 0.1, on time 0.9. Path products: 0.075, 0.225, 0.07 and 0.63.</title>\n  <g stroke=\"currentColor\" stroke-width=\"1.5\" fill=\"none\">\n    <line x1=\"20\" y1=\"125\" x2=\"135\" y2=\"65\"/>\n    <line x1=\"20\" y1=\"125\" x2=\"135\" y2=\"185\"/>\n    <line x1=\"165\" y1=\"65\" x2=\"280\" y2=\"30\"/>\n    <line x1=\"165\" y1=\"65\" x2=\"280\" y2=\"100\"/>\n    <line x1=\"165\" y1=\"185\" x2=\"280\" y2=\"150\"/>\n    <line x1=\"165\" y1=\"185\" x2=\"280\" y2=\"220\"/>\n  </g>\n  <g font-family=\"inherit\" font-size=\"14\" fill=\"currentColor\">\n    <text x=\"142\" y=\"70\" fill=\"var(--t1-ink)\" font-weight=\"bold\">R</text>\n    <text x=\"142\" y=\"190\" fill=\"var(--t1-ink)\" font-weight=\"bold\">R′</text>\n    <text x=\"288\" y=\"35\" fill=\"var(--t2-ink)\" font-weight=\"bold\">L</text>\n    <text x=\"288\" y=\"105\" fill=\"var(--t2-ink)\" font-weight=\"bold\">L′</text>\n    <text x=\"288\" y=\"155\" fill=\"var(--t2-ink)\" font-weight=\"bold\">L</text>\n    <text x=\"288\" y=\"225\" fill=\"var(--t2-ink)\" font-weight=\"bold\">L′</text>\n  </g>\n  <g font-family=\"inherit\" font-size=\"13\" fill=\"currentColor\">\n    <text x=\"58\" y=\"82\">0.3</text>\n    <text x=\"58\" y=\"180\">0.7</text>\n    <text x=\"205\" y=\"36\">0.25</text>\n    <text x=\"205\" y=\"104\">0.75</text>\n    <text x=\"210\" y=\"156\">0.1</text>\n    <text x=\"210\" y=\"224\">0.9</text>\n  </g>\n  <g font-family=\"inherit\" font-size=\"13\" fill=\"var(--muted)\">\n    <text x=\"318\" y=\"35\">0.3 × 0.25 = 0.075</text>\n    <text x=\"318\" y=\"105\">0.3 × 0.75 = 0.225</text>\n    <text x=\"318\" y=\"155\">0.7 × 0.1 = 0.07</text>\n    <text x=\"318\" y=\"225\">0.7 × 0.9 = 0.63</text>\n  </g>\n</svg>",
  "4-6-venn-regions": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 260\" role=\"img\" aria-labelledby=\"t\">\n  <title id=\"t\">A rectangle labelled U holds two overlapping circles, A on the left and B on the right. The four regions are labelled: A and not B, A and B in the overlap, not A and B, and not A and not B outside both circles.</title>\n  <rect x=\"10\" y=\"10\" width=\"400\" height=\"240\" rx=\"6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/>\n  <circle cx=\"165\" cy=\"128\" r=\"88\" fill=\"var(--t1-ink)\" fill-opacity=\"0.12\" stroke=\"var(--t1-ink)\" stroke-width=\"2\"/>\n  <circle cx=\"255\" cy=\"128\" r=\"88\" fill=\"var(--t2-ink)\" fill-opacity=\"0.12\" stroke=\"var(--t2-ink)\" stroke-width=\"2\"/>\n  <g font-family=\"inherit\" font-size=\"15\">\n    <text x=\"24\" y=\"34\" fill=\"currentColor\">U</text>\n    <text x=\"92\" y=\"52\" fill=\"var(--t1-ink)\" font-weight=\"bold\">A</text>\n    <text x=\"318\" y=\"52\" fill=\"var(--t2-ink)\" font-weight=\"bold\">B</text>\n  </g>\n  <g font-family=\"inherit\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">\n    <text x=\"125\" y=\"133\">A ∩ B′</text>\n    <text x=\"210\" y=\"133\">A ∩ B</text>\n    <text x=\"295\" y=\"133\">A′ ∩ B</text>\n    <text x=\"340\" y=\"236\">A′ ∩ B′</text>\n  </g>\n</svg>",
